<?php /** @var array $invoice */ /** @var array $adjustments */ ?>
<!doctype html><html><head><meta charset="utf-8"><title>Invoice Adjustments</title><style>body{font-family:system-ui;margin:32px;max-width:1000px}.card{border:1px solid #ddd;border-radius:10px;padding:20px;margin-bottom:20px}input,select,textarea,button{padding:10px;margin:5px 0;width:100%;box-sizing:border-box}button{cursor:pointer}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}</style></head><body>
<h1>Invoice Adjustments</h1><p><strong><?=htmlspecialchars($invoice['invoice_no'])?></strong> · <?=htmlspecialchars($invoice['admission_no'].' - '.$invoice['first_name'].' '.$invoice['last_name'])?></p><div class="card"><strong>Total:</strong> KES <?=number_format((float)$invoice['total'],2)?> &nbsp; <strong>Paid:</strong> KES <?=number_format((float)$invoice['paid_amount'],2)?> &nbsp; <strong>Balance:</strong> KES <?=number_format((float)$invoice['balance'],2)?></div>
<div class="card"><h2>Apply discount / waiver / credit</h2><form method="post" action="/finance/invoices/<?=$invoice['id']?>/adjustments"><input type="hidden" name="invoice_id" value="<?=$invoice['id']?>"><div class="grid"><div><label>Type</label><select name="type"><option value="discount">Discount</option><option value="waiver">Waiver</option><option value="credit">Credit</option></select></div><div><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" max="<?=htmlspecialchars($invoice['balance'])?>" required></div></div><label>Reason</label><textarea name="reason" required></textarea><label>Reference (optional)</label><input name="reference"><button type="submit">Apply Adjustment</button></form></div>
<div class="card"><h2>Adjustment history</h2><table><tr><th>Type</th><th>Amount</th><th>Reason</th><th>Reference</th><th>Date</th></tr><?php foreach($adjustments as $a):?><tr><td><?=htmlspecialchars(ucfirst($a['type']))?></td><td>KES <?=number_format((float)$a['amount'],2)?></td><td><?=htmlspecialchars($a['reason'])?></td><td><?=htmlspecialchars($a['reference']??'')?></td><td><?=htmlspecialchars($a['created_at'])?></td></tr><?php endforeach;?></table></div></body></html>
